-- SPEED dossiers (WI-OI-120ca, SPEED S7; plan v1.4 §4.2). Forward-only; structure only, no business rows.
--
-- A dossier is requested, generated by the module's worker into the object store, and kept with the SHA-256 of each
-- file. It is never regenerated in place: a new request is a new dossier. Its model (the eight sections) is kept as it
-- was generated, so the files can always be checked against it.

BEGIN;

CREATE TABLE gigalibs_speed.dossiers (
  id uuid PRIMARY KEY,
  tenant_id varchar(64) NOT NULL,
  request_key uuid NOT NULL,
  route_id uuid NOT NULL,
  route_version integer NOT NULL CHECK (route_version > 0),
  status varchar(16) NOT NULL DEFAULT 'QUEUED' CHECK (status IN ('QUEUED', 'RUNNING', 'DONE', 'FAILED')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  -- Bumped by every change of status; the version of each fact about the dossier.
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  watermarked boolean NOT NULL,
  model jsonb CHECK (model IS NULL OR jsonb_typeof(model) = 'object'),
  docx_key varchar(500),
  docx_sha256 char(64) CHECK (docx_sha256 IS NULL OR docx_sha256 ~ '^[0-9a-f]{64}$'),
  docx_bytes integer CHECK (docx_bytes IS NULL OR docx_bytes > 0),
  pdf_key varchar(500),
  pdf_sha256 char(64) CHECK (pdf_sha256 IS NULL OR pdf_sha256 ~ '^[0-9a-f]{64}$'),
  pdf_bytes integer CHECK (pdf_bytes IS NULL OR pdf_bytes > 0),
  error_code varchar(64),
  requested_by varchar(128) NOT NULL,
  requested_at timestamptz NOT NULL DEFAULT now(),
  started_at timestamptz,
  completed_at timestamptz,
  UNIQUE (tenant_id, request_key),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, route_id) REFERENCES gigalibs_speed.routes (tenant_id, id),
  CHECK ((status = 'DONE') = (model IS NOT NULL AND docx_key IS NOT NULL AND docx_sha256 IS NOT NULL AND pdf_key IS NOT NULL
    AND pdf_sha256 IS NOT NULL AND completed_at IS NOT NULL)),
  CHECK ((status = 'FAILED') = (error_code IS NOT NULL))
);
CREATE INDEX dossiers_route ON gigalibs_speed.dossiers (tenant_id, route_id, requested_at DESC);
CREATE INDEX dossiers_queue ON gigalibs_speed.dossiers (status, requested_at) WHERE status IN ('QUEUED', 'RUNNING');

-- A finished dossier never changes, and no dossier is deleted.
CREATE FUNCTION gigalibs_speed.keep_dossier() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'SPEED dossiers are never deleted' USING ERRCODE = '55000';
  END IF;
  IF OLD.status IN ('DONE', 'FAILED') THEN
    RAISE EXCEPTION 'A finished SPEED dossier never changes; request a new one' USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER dossiers_kept BEFORE UPDATE OR DELETE ON gigalibs_speed.dossiers
FOR EACH ROW EXECUTE FUNCTION gigalibs_speed.keep_dossier();

ALTER TABLE gigalibs_speed.dossiers ENABLE ROW LEVEL SECURITY;
ALTER TABLE gigalibs_speed.dossiers FORCE ROW LEVEL SECURITY;
CREATE POLICY dossiers_tenant_isolation ON gigalibs_speed.dossiers
  FOR ALL USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), ''))
  WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), ''));

-- The worker's only cross-tenant read (the platform's relay pattern): which tenants have dossiers waiting, oldest first.
-- Each dossier is then claimed inside its tenant's transaction, with FOR UPDATE SKIP LOCKED.
CREATE FUNCTION gigalibs_speed.list_dossier_tenants(p_limit integer)
RETURNS TABLE(tenant_id character varying)
LANGUAGE sql
SECURITY DEFINER
SET search_path = gigalibs_speed, pg_temp
AS $$
  SELECT d.tenant_id FROM gigalibs_speed.dossiers d
   WHERE d.status IN ('QUEUED', 'RUNNING')
   GROUP BY d.tenant_id
   ORDER BY min(d.requested_at)
   LIMIT p_limit
$$;
REVOKE ALL ON FUNCTION gigalibs_speed.list_dossier_tenants(integer) FROM PUBLIC;

INSERT INTO gigalibs_speed.schema_migrations (version, name)
VALUES (5, '000005_speed_dossiers');

COMMIT;
